static const pet_anim_sequence_t *lookup_asset(const char *asset)
{
    if (!asset || !asset[0]) return PET_BIG_ANIM_IDLE;
    for (size_t i = 0; i < ARRAY_SIZE(PET_BIG_ANIM_ASSET_MAP); ++i) {
        if (strcmp(PET_BIG_ANIM_ASSET_MAP[i].asset, asset) == 0) {
            return PET_BIG_ANIM_ASSET_MAP[i].sequence;
        }
    }
    return PET_BIG_ANIM_IDLE;
}

const pet_anim_sequence_t *ui_pet_big_anim_for_asset(const char *asset)
{
    return lookup_asset(asset);
}

const pet_anim_sequence_t *ui_pet_big_anim_idle(void)
{
    return PET_BIG_ANIM_IDLE;
}

const pet_anim_sequence_t *ui_pet_big_anim_for_state(const char *state)
{
    if (!state || !state[0]) return ui_pet_big_anim_idle();
    for (size_t i = 0; i < ARRAY_SIZE(PET_BIG_ANIM_STATE_MAP); ++i) {
        if (strcmp(PET_BIG_ANIM_STATE_MAP[i].state, state) == 0) {
            return lookup_asset(PET_BIG_ANIM_STATE_MAP[i].asset);
        }
    }
    return ui_pet_big_anim_idle();
}
